    // Inner model class
    static class NameItem {
        int number;
        String arabicName;
        String meaning;

        NameItem(int number, String arabicName, String meaning) {
            this.number = number;
            this.arabicName = arabicName;
            this.meaning = meaning;
        }
    }

    // RecyclerView Adapter
    static class AsmaulHusnaAdapter extends RecyclerView.Adapter<AsmaulHusnaAdapter.ViewHolder> {
        private final List<NameItem> items;

        AsmaulHusnaAdapter(List<NameItem> items) {
            this.items = items;
        }

        @NonNull
        @Override
        public ViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
            View v = LayoutInflater.from(parent.getContext())
                    .inflate(R.layout.item_asmaul_husna, parent, false);
            return new ViewHolder(v);
        }

        @Override
        public void onBindViewHolder(@NonNull ViewHolder holder, int position) {
            NameItem item = items.get(position);
            holder.number.setText(String.valueOf(item.number));
            holder.arabicName.setText(item.arabicName);
            holder.meaning.setText(item.meaning);
        }

        @Override
        public int getItemCount() {
            return items.size();
        }

        static class ViewHolder extends RecyclerView.ViewHolder {
            TextView number, arabicName, meaning;

            ViewHolder(View v) {
                super(v);
                number = v.findViewById(R.id.tv_name_number);
                arabicName = v.findViewById(R.id.tv_name_arabic);
                meaning = v.findViewById(R.id.tv_name_meaning);
            }
        }
    }
